    devices[2]["type"] = "mmi"
    devices[3]["type"] = "coupler"
    nets = [_mk_net(f"d{i:03d}", f"d{(i + 1) % 100:03d}") for i in range(100)]
    return {"devices": devices, "nets": nets}


